// Topic index for Scripture search. Texts come from the 1961 Korean Revised Version and the KJV (public domain).
export const VERSE_TOPICS = [{"id": "comfort", "ko": "위로", "en": "Comfort", "kw": ["위로", "위안", "힘들", "지칠", "괴로", "상처", "마음", "아픈", "comfort", "hurt", "tired", "weary", "sad"], "v": [{"k": "마태복음 11:28", "e": "Matthew 11:28", "tk": "수고하고 무거운 짐진 자들아 다 내게로 오라 내가 너희를 쉬게 하리라", "te": "Come unto me, all ye that labour and are heavy laden, and I will give you rest."}, {"k": "시편 34:18", "e": "Psalm 34:18", "tk": "여호와는 마음이 상한 자에게 가까이 하시고 중심에 통회하는 자를 구원하시는도다", "te": "The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit."}, {"k": "고린도후서 1:3", "e": "2 Corinthians 1:3", "tk": "찬송하리로다 그는 우리 주 예수 그리스도의 하나님이시요 자비의 아버지시요 모든 위로의 하나님이시며", "te": "Blessed be God, even the Father of our Lord Jesus Christ, the Father of mercies, and the God of all comfort;"}, {"k": "시편 147:3", "e": "Psalm 147:3", "tk": "상심한 자를 고치시며 저희 상처를 싸매시는도다", "te": "He healeth the broken in heart, and bindeth up their wounds."}, {"k": "이사야 41:10", "e": "Isaiah 41:10", "tk": "두려워 말라 내가 너와 함께 함이니라 놀라지 말라 나는 네 하나님이 됨이니라 내가 너를 굳세게 하리라 참으로 너를 도와 주리라 참으로 나의 의로운 오른손으로 너를 붙들리라", "te": "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness."}, {"k": "요한계시록 21:4", "e": "Revelation 21:4", "tk": "모든 눈물을 그 눈에서 씻기시매 다시 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니 처음 것들이 다 지나갔음이러라", "te": "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away."}, {"k": "요한복음 14:1", "e": "John 14:1", "tk": "너희는 마음에 근심하지 말라 하나님을 믿으니 또 나를 믿으라", "te": "Let not your heart be troubled: ye believe in God, believe also in me."}, {"k": "시편 23:4", "e": "Psalm 23:4", "tk": "내가 사망의 음침한 골짜기로 다닐찌라도 해를 두려워하지 않을 것은 주께서 나와 함께 하심이라 주의 지팡이와 막대기가 나를 안위하시나이다", "te": "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me."}, {"k": "마태복음 5:4", "e": "Matthew 5:4", "tk": "애통하는 자는 복이 있나니 저희가 위로를 받을 것임이요", "te": "Blessed are they that mourn: for they shall be comforted."}, {"k": "이사야 40:1", "e": "Isaiah 40:1", "tk": "너희 하나님이 가라사대 너희는 위로하라 내 백성을 위로하라", "te": "Comfort ye, comfort ye my people, saith your God."}]}, {"id": "peace", "ko": "평안", "en": "Peace", "kw": ["평안", "평화", "평강", "안식", "고요", "peace", "calm", "still"], "v": [{"k": "요한복음 14:27", "e": "John 14:27", "tk": "평안을 너희에게 끼치노니 곧 나의 평안을 너희에게 주노라 내가 너희에게 주는 것은 세상이 주는 것 같지 아니하니라 너희는 마음에 근심도 말고 두려워하지도 말라", "te": "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid."}, {"k": "빌립보서 4:7", "e": "Philippians 4:7", "tk": "그리하면 모든 지각에 뛰어난 하나님의 평강이 그리스도 예수 안에서 너희 마음과 생각을 지키시리라", "te": "And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus."}, {"k": "이사야 26:3", "e": "Isaiah 26:3", "tk": "주께서 심지가 견고한 자를 평강에 평강으로 지키시리니 이는 그가 주를 의뢰함이니이다", "te": "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee."}, {"k": "민수기 6:26", "e": "Numbers 6:26", "tk": "여호와는 그 얼굴을 네게로 향하여 드사 평강 주시기를 원하노라 할찌니라 하라", "te": "The LORD lift up his countenance upon thee, and give thee peace."}, {"k": "로마서 15:13", "e": "Romans 15:13", "tk": "소망의 하나님이 모든 기쁨과 평강을 믿음 안에서 너희에게 충만케 하사 성령의 능력으로 소망이 넘치게 하시기를 원하노라", "te": "Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost."}, {"k": "골로새서 3:15", "e": "Colossians 3:15", "tk": "그리스도의 평강이 너희 마음을 주장하게 하라 평강을 위하여 너희가 한 몸으로 부르심을 받았나니 또한 너희는 감사하는 자가 되라", "te": "And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful."}, {"k": "시편 4:8", "e": "Psalm 4:8", "tk": "내가 평안히 눕고 자기도 하리니 나를 안전히 거하게 하시는 이는 오직 여호와시니이다", "te": "I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety."}, {"k": "데살로니가후서 3:16", "e": "2 Thessalonians 3:16", "tk": "평강의 주께서 친히 때마다 일마다 너희에게 평강을 주시기를 원하노라 주는 너희 모든 사람과 함께 하실찌어다", "te": "Now the Lord of peace himself give you peace always by all means. The Lord be with you all."}, {"k": "시편 46:10", "e": "Psalm 46:10", "tk": "이르시기를 너희는 가만히 있어 내가 하나님 됨을 알찌어다 내가 열방과 세계 중에서 높임을 받으리라 하시도다", "te": "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth."}]}, {"id": "thanks", "ko": "감사", "en": "Thankfulness", "kw": ["감사", "고마", "추수", "감사절", "thanks", "thankful", "grateful", "gratitude", "thanksgiving"], "v": [{"k": "데살로니가전서 5:18", "e": "1 Thessalonians 5:18", "tk": "범사에 감사하라 이는 그리스도 예수 안에서 너희를 향하신 하나님의 뜻이니라", "te": "In every thing give thanks: for this is the will of God in Christ Jesus concerning you."}, {"k": "시편 100:4", "e": "Psalm 100:4", "tk": "감사함으로 그 문에 들어가며 찬송함으로 그 궁정에 들어가서 그에게 감사하며 그 이름을 송축할찌어다", "te": "Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name."}, {"k": "시편 107:1", "e": "Psalm 107:1", "tk": "여호와께 감사하라 그는 선하시며 그 인자하심이 영원함이로다", "te": "O give thanks unto the LORD, for he is good: for his mercy endureth for ever."}, {"k": "시편 136:1", "e": "Psalm 136:1", "tk": "여호와께 감사하라 그는 선하시며 그 인자하심이 영원함이로다", "te": "O give thanks unto the LORD; for he is good: for his mercy endureth for ever."}, {"k": "골로새서 3:17", "e": "Colossians 3:17", "tk": "또 무엇을 하든지 말에나 일에나 다 주 예수의 이름으로 하고 그를 힘입어 하나님 아버지께 감사하라", "te": "And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him."}, {"k": "에베소서 5:20", "e": "Ephesians 5:20", "tk": "범사에 우리 주 예수 그리스도의 이름으로 항상 아버지 하나님께 감사하며", "te": "Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;"}, {"k": "시편 9:1", "e": "Psalm 9:1", "tk": "내가 전심으로 여호와께 감사하오며 주의 모든 기사를 전하리이다", "te": "I will praise thee, O LORD, with my whole heart; I will shew forth all thy marvellous works."}, {"k": "빌립보서 4:6", "e": "Philippians 4:6", "tk": "아무 것도 염려하지 말고 오직 모든 일에 기도와 간구로, 너희 구할 것을 감사함으로 하나님께 아뢰라", "te": "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God."}]}, {"id": "love", "ko": "사랑", "en": "Love", "kw": ["사랑", "연인", "love"], "v": [{"k": "고린도전서 13:4", "e": "1 Corinthians 13:4", "tk": "사랑은 오래 참고 사랑은 온유하며 투기하는 자가 되지 아니하며 사랑은 자랑하지 아니하며 교만하지 아니하며", "te": "Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,"}, {"k": "고린도전서 13:7", "e": "1 Corinthians 13:7", "tk": "모든 것을 참으며 모든 것을 믿으며 모든 것을 바라며 모든 것을 견디느니라", "te": "Beareth all things, believeth all things, hopeth all things, endureth all things."}, {"k": "고린도전서 13:13", "e": "1 Corinthians 13:13", "tk": "그런즉 믿음, 소망, 사랑, 이 세 가지는 항상 있을 것인데 그 중에 제일은 사랑이라", "te": "And now abideth faith, hope, charity, these three; but the greatest of these is charity."}, {"k": "요한복음 15:12", "e": "John 15:12", "tk": "내 계명은 곧 내가 너희를 사랑한 것 같이 너희도 서로 사랑하라 하는 이것이니라", "te": "This is my commandment, That ye love one another, as I have loved you."}, {"k": "요한일서 4:7", "e": "1 John 4:7", "tk": "사랑하는 자들아 우리가 서로 사랑하자 사랑은 하나님께 속한것이니 사랑하는 자마다 하나님께로 나서 하나님을 알고", "te": "Beloved, let us love one another: for love is of God; and every one that loveth is born of God, and knoweth God."}, {"k": "요한일서 4:8", "e": "1 John 4:8", "tk": "사랑하지 아니하는 자는 하나님을 알지 못하나니 이는 하나님은 사랑이심이라", "te": "He that loveth not knoweth not God; for God is love."}, {"k": "요한일서 4:19", "e": "1 John 4:19", "tk": "우리가 사랑함은 그가 먼저 우리를 사랑하셨음이라", "te": "We love him, because he first loved us."}, {"k": "로마서 8:39", "e": "Romans 8:39", "tk": "높음이나 깊음이나 다른 아무 피조물이라도 우리를 우리 주 그리스도 예수 안에 있는 하나님의 사랑에서 끊을 수 없으리라", "te": "Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord."}, {"k": "요한복음 3:16", "e": "John 3:16", "tk": "하나님이 세상을 이처럼 사랑하사 독생자를 주셨으니 이는 저를 믿는 자마다 멸망치 않고 영생을 얻게 하려 하심이니라", "te": "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."}, {"k": "아가 8:7", "e": "Song of Solomon 8:7", "tk": "이 사랑은 많은 물이 꺼치지 못하겠고 홍수라도 엄몰하지 못하나니 사람이 그 온 가산을 다 주고 사랑과 바꾸려 할찌라도 오히려 멸시를 받으리라", "te": "Many waters cannot quench love, neither can the floods drown it: if a man would give all the substance of his house for love, it would utterly be contemned."}, {"k": "골로새서 3:14", "e": "Colossians 3:14", "tk": "이 모든 것 위에 사랑을 더하라 이는 온전하게 매는 띠니라", "te": "And above all these things put on charity, which is the bond of perfectness."}, {"k": "베드로전서 4:8", "e": "1 Peter 4:8", "tk": "무엇보다도 열심으로 서로 사랑할찌니 사랑은 허다한 죄를 덮느니라", "te": "And above all things have fervent charity among yourselves: for charity shall cover the multitude of sins."}]}, {"id": "courage", "ko": "용기", "en": "Courage", "kw": ["용기", "담대", "두려", "강하", "courage", "brave", "bold"], "v": [{"k": "여호수아 1:9", "e": "Joshua 1:9", "tk": "내가 네게 명한 것이 아니냐 마음을 강하게 하고 담대히 하라 두려워 말며 놀라지 말라 네가 어디로 가든지 네 하나님 여호와가 너와 함께 하느니라 하시니라", "te": "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest."}, {"k": "신명기 31:6", "e": "Deuteronomy 31:6", "tk": "너는 마음을 강하게 하고 담대히 하라 그들을 두려워 말라 그들 앞에서 떨지 말라 이는 네 하나님 여호와 그가 너와 함께 행하실 것임이라 반드시 너를 떠나지 아니하시며 버리지 아니하시리라 하고", "te": "Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee."}, {"k": "이사야 41:10", "e": "Isaiah 41:10", "tk": "두려워 말라 내가 너와 함께 함이니라 놀라지 말라 나는 네 하나님이 됨이니라 내가 너를 굳세게 하리라 참으로 너를 도와 주리라 참으로 나의 의로운 오른손으로 너를 붙들리라", "te": "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness."}, {"k": "시편 27:1", "e": "Psalm 27:1", "tk": "여호와는 나의 빛이요 나의 구원이시니 내가 누구를 두려워하리요 여호와는 내 생명의 능력이시니 내가 누구를 무서워하리요", "te": "The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?"}, {"k": "디모데후서 1:7", "e": "2 Timothy 1:7", "tk": "하나님이 우리에게 주신 것은 두려워하는 마음이 아니요 오직 능력과 사랑과 근신하는 마음이니", "te": "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind."}, {"k": "시편 31:24", "e": "Psalm 31:24", "tk": "강하고 담대하라 여호와를 바라는 너희들아", "te": "Be of good courage, and he shall strengthen your heart, all ye that hope in the LORD."}, {"k": "고린도전서 16:13", "e": "1 Corinthians 16:13", "tk": "깨어 믿음에 굳게 서서 남자답게 강건하여라", "te": "Watch ye, stand fast in the faith, quit you like men, be strong."}, {"k": "시편 56:3", "e": "Psalm 56:3", "tk": "내가 두려워하는 날에는 주를 의지하리이다", "te": "What time I am afraid, I will trust in thee."}]}, {"id": "strength", "ko": "힘·능력", "en": "Strength", "kw": ["힘", "능력", "지치", "새힘", "strength", "strong", "power", "weak"], "v": [{"k": "빌립보서 4:13", "e": "Philippians 4:13", "tk": "내게 능력 주시는 자 안에서 내가 모든 것을 할 수 있느니라", "te": "I can do all things through Christ which strengtheneth me."}, {"k": "이사야 40:31", "e": "Isaiah 40:31", "tk": "오직 여호와를 앙망하는 자는 새 힘을 얻으리니 독수리의 날개치며 올라감 같을 것이요 달음박질하여도 곤비치 아니하겠고 걸어가도 피곤치 아니하리로다", "te": "But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint."}, {"k": "시편 46:1", "e": "Psalm 46:1", "tk": "하나님은 우리의 피난처시요 힘이시니 환난 중에 만날 큰 도움이시라", "te": "God is our refuge and strength, a very present help in trouble."}, {"k": "느헤미야 8:10", "e": "Nehemiah 8:10", "tk": "느헤미야가 또 이르기를 너희는 가서 살진 것을 먹고 단 것을 마시되 예비치 못한 자에게는 너희가 나누어 주라 이 날은 우리 주의 성일이니 근심하지 말라 여호와를 기뻐하는 것이 너희의 힘이니라 하고", "te": "Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength."}, {"k": "시편 28:7", "e": "Psalm 28:7", "tk": "여호와는 나의 힘과 나의 방패시니 내 마음이 저를 의지하여 도움을 얻었도다 그러므로 내 마음이 크게 기뻐하며 내 노래로 저를 찬송하리로다", "te": "The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him."}, {"k": "고린도후서 12:9", "e": "2 Corinthians 12:9", "tk": "내게 이르시기를 내 은혜가 네게 족하도다 이는 내 능력이 약한데서 온전하여짐이라 하신지라 이러므로 도리어 크게 기뻐함으로 나의 여러 약한 것들에 대하여 자랑하리니 이는 그리스도의 능력으로 내게 머물게 하려함이라", "te": "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me."}, {"k": "이사야 40:29", "e": "Isaiah 40:29", "tk": "피곤한 자에게는 능력을 주시며 무능한 자에게는 힘을 더하시나니", "te": "He giveth power to the faint; and to them that have no might he increaseth strength."}, {"k": "시편 18:2", "e": "Psalm 18:2", "tk": "여호와는 나의 반석이시요 나의 요새시요 나를 건지시는 자시요 나의 하나님이시요 나의 피할 바위시요 나의 방패시요 나의 구원의 뿔이시요 나의 산성이시로다", "te": "The LORD is my rock, and my fortress, and my deliverer; my God, my strength, in whom I will trust; my buckler, and the horn of my salvation, and my high tower."}]}, {"id": "hope", "ko": "소망", "en": "Hope", "kw": ["소망", "희망", "미래", "장래", "hope", "future"], "v": [{"k": "예레미야 29:11", "e": "Jeremiah 29:11", "tk": "나 여호와가 말하노라 너희를 향한 나의 생각은 내가 아나니 재앙이 아니라 곧 평안이요 너희 장래에 소망을 주려하는 생각이라", "te": "For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end."}, {"k": "로마서 15:13", "e": "Romans 15:13", "tk": "소망의 하나님이 모든 기쁨과 평강을 믿음 안에서 너희에게 충만케 하사 성령의 능력으로 소망이 넘치게 하시기를 원하노라", "te": "Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost."}, {"k": "시편 42:11", "e": "Psalm 42:11", "tk": "내 영혼아 네가 어찌하여 낙망하며 어찌하여 내 속에서 불안하여 하는고 너는 하나님을 바라라 나는 내 얼굴을 도우시는 내 하나님을 오히려 찬송하리로다", "te": "Why art thou cast down, O my soul? and why art thou disquieted within me? hope thou in God: for I shall yet praise him, who is the health of my countenance, and my God."}, {"k": "히브리서 11:1", "e": "Hebrews 11:1", "tk": "믿음은 바라는 것들의 실상이요 보지 못하는 것들의 증거니", "te": "Now faith is the substance of things hoped for, the evidence of things not seen."}, {"k": "예레미야애가 3:22", "e": "Lamentations 3:22", "tk": "여호와의 자비와 긍휼이 무궁하시므로 우리가 진멸되지 아니함이니이다", "te": "It is of the LORD’s mercies that we are not consumed, because his compassions fail not."}, {"k": "예레미야애가 3:23", "e": "Lamentations 3:23", "tk": "이것이 아침마다 새로우니 주의 성실이 크도소이다", "te": "They are new every morning: great is thy faithfulness."}, {"k": "로마서 12:12", "e": "Romans 12:12", "tk": "소망 중에 즐거워하며 환난 중에 참으며 기도에 항상 힘쓰며", "te": "Rejoicing in hope; patient in tribulation; continuing instant in prayer;"}, {"k": "시편 39:7", "e": "Psalm 39:7", "tk": "주여 내가 무엇을 바라리요 나의 소망은 주께 있나이다", "te": "And now, Lord, what wait I for? my hope is in thee."}]}, {"id": "joy", "ko": "기쁨", "en": "Joy", "kw": ["기쁨", "기뻐", "즐거", "행복", "joy", "rejoice", "happy", "glad"], "v": [{"k": "빌립보서 4:4", "e": "Philippians 4:4", "tk": "주 안에서 항상 기뻐하라 내가 다시 말하노니 기뻐하라", "te": "Rejoice in the Lord alway: and again I say, Rejoice."}, {"k": "느헤미야 8:10", "e": "Nehemiah 8:10", "tk": "느헤미야가 또 이르기를 너희는 가서 살진 것을 먹고 단 것을 마시되 예비치 못한 자에게는 너희가 나누어 주라 이 날은 우리 주의 성일이니 근심하지 말라 여호와를 기뻐하는 것이 너희의 힘이니라 하고", "te": "Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength."}, {"k": "시편 16:11", "e": "Psalm 16:11", "tk": "주께서 생명의 길로 내게 보이시리니 주의 앞에는 기쁨이 충만하고 주의 우편에는 영원한 즐거움이 있나이다", "te": "Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore."}, {"k": "시편 118:24", "e": "Psalm 118:24", "tk": "이 날은 여호와의 정하신 것이라 이 날에 우리가 즐거워하고 기뻐하리로다", "te": "This is the day which the LORD hath made; we will rejoice and be glad in it."}, {"k": "시편 126:3", "e": "Psalm 126:3", "tk": "여호와께서 우리를 위하여 대사를 행하셨으니 우리는 기쁘도다", "te": "The LORD hath done great things for us; whereof we are glad."}, {"k": "요한복음 15:11", "e": "John 15:11", "tk": "내가 이것을 너희에게 이름은 내 기쁨이 너희 안에 있어 너희 기쁨을 충만하게 하려함이니라", "te": "These things have I spoken unto you, that my joy might remain in you, and that your joy might be full."}, {"k": "데살로니가전서 5:16", "e": "1 Thessalonians 5:16", "tk": "항상 기뻐하라", "te": "Rejoice evermore."}]}, {"id": "faith", "ko": "믿음", "en": "Faith", "kw": ["믿음", "신앙", "신뢰", "의지", "faith", "believe", "trust"], "v": [{"k": "히브리서 11:1", "e": "Hebrews 11:1", "tk": "믿음은 바라는 것들의 실상이요 보지 못하는 것들의 증거니", "te": "Now faith is the substance of things hoped for, the evidence of things not seen."}, {"k": "히브리서 11:6", "e": "Hebrews 11:6", "tk": "믿음이 없이는 기쁘시게 못하나니 하나님께 나아가는 자는 반드시 그가 계신 것과 또한 그가 자기를 찾는 자들에게 상 주시는 이심을 믿어야 할찌니라", "te": "But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him."}, {"k": "마가복음 9:23", "e": "Mark 9:23", "tk": "예수께서 이르시되 할 수 있거든이 무슨 말이냐 믿는 자에게는 능치 못할 일이 없느니라 하시니", "te": "Jesus said unto him, If thou canst believe, all things are possible to him that believeth."}, {"k": "고린도후서 5:7", "e": "2 Corinthians 5:7", "tk": "이는 우리가 믿음으로 행하고 보는 것으로 하지 아니함이로라", "te": "(For we walk by faith, not by sight:)"}, {"k": "로마서 10:17", "e": "Romans 10:17", "tk": "그러므로 믿음은 들음에서 나며 들음은 그리스도의 말씀으로 말미암았느니라", "te": "So then faith cometh by hearing, and hearing by the word of God."}, {"k": "잠언 3:5", "e": "Proverbs 3:5", "tk": "너는 마음을 다하여 여호와를 의뢰하고 네 명철을 의지하지 말라", "te": "Trust in the LORD with all thine heart; and lean not unto thine own understanding."}, {"k": "잠언 3:6", "e": "Proverbs 3:6", "tk": "너는 범사에 그를 인정하라 그리하면 네 길을 지도하시리라", "te": "In all thy ways acknowledge him, and he shall direct thy paths."}, {"k": "갈라디아서 2:20", "e": "Galatians 2:20", "tk": "내가 그리스도와 함께 십자가에 못 박혔나니 그런즉 이제는 내가 산 것이 아니요 오직 내 안에 그리스도께서 사신 것이라 이제 내가 육체 가운데 사는 것은 나를 사랑하사 나를 위하여 자기 몸을 버리신 하나님의 아들을 믿는 믿음 안에서 사는 것이라", "te": "I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me."}]}, {"id": "prayer", "ko": "기도", "en": "Prayer", "kw": ["기도", "간구", "구하", "prayer", "pray", "ask"], "v": [{"k": "데살로니가전서 5:17", "e": "1 Thessalonians 5:17", "tk": "쉬지 말고 기도하라", "te": "Pray without ceasing."}, {"k": "빌립보서 4:6", "e": "Philippians 4:6", "tk": "아무 것도 염려하지 말고 오직 모든 일에 기도와 간구로, 너희 구할 것을 감사함으로 하나님께 아뢰라", "te": "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God."}, {"k": "마태복음 7:7", "e": "Matthew 7:7", "tk": "구하라 그러면 너희에게 주실 것이요 찾으라 그러면 찾을 것이요 문을 두드리라 그러면 너희에게 열릴 것이니", "te": "Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:"}, {"k": "예레미야 33:3", "e": "Jeremiah 33:3", "tk": "너는 내게 부르짖으라 내가 네게 응답하겠고 네가 알지 못하는 크고 비밀한 일을 네게 보이리라", "te": "Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not."}, {"k": "야고보서 5:16", "e": "James 5:16", "tk": "이러므로 너희 죄를 서로 고하며 병 낫기를 위하여 서로 기도하라 의인의 간구는 역사하는 힘이 많으니라", "te": "Confess your faults one to another, and pray one for another, that ye may be healed. The effectual fervent prayer of a righteous man availeth much."}, {"k": "마태복음 6:9", "e": "Matthew 6:9", "tk": "그러므로 너희는 이렇게 기도하라 하늘에 계신 우리 아버지여 이름이 거룩히 여김을 받으시오며", "te": "After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name."}, {"k": "시편 145:18", "e": "Psalm 145:18", "tk": "여호와께서는 자기에게 간구하는 모든 자 곧 진실하게 간구하는 모든 자에게 가까이 하시는도다", "te": "The LORD is nigh unto all them that call upon him, to all that call upon him in truth."}, {"k": "마가복음 11:24", "e": "Mark 11:24", "tk": "그러므로 내가 너희에게 말하노니 무엇이든지 기도하고 구하는 것은 받은 줄로 믿으라 그리하면 너희에게 그대로 되리라", "te": "Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them."}]}, {"id": "guidance", "ko": "인도하심", "en": "Guidance", "kw": ["인도", "길", "방향", "목자", "guidance", "path", "way", "lead", "shepherd"], "v": [{"k": "시편 23:1", "e": "Psalm 23:1", "tk": "여호와는 나의 목자시니 내가 부족함이 없으리로다", "te": "The LORD is my shepherd; I shall not want."}, {"k": "시편 23:2", "e": "Psalm 23:2", "tk": "그가 나를 푸른 초장에 누이시며 쉴만한 물 가으로 인도하시는도다", "te": "He maketh me to lie down in green pastures: he leadeth me beside the still waters."}, {"k": "시편 23:3", "e": "Psalm 23:3", "tk": "내 영혼을 소생시키시고 자기 이름을 위하여 의의 길로 인도하시는도다", "te": "He restoreth my soul: he leadeth me in the paths of righteousness for his name’s sake."}, {"k": "잠언 3:6", "e": "Proverbs 3:6", "tk": "너는 범사에 그를 인정하라 그리하면 네 길을 지도하시리라", "te": "In all thy ways acknowledge him, and he shall direct thy paths."}, {"k": "시편 119:105", "e": "Psalm 119:105", "tk": "주의 말씀은 내 발에 등이요 내 길에 빛이니이다", "te": "Thy word is a lamp unto my feet, and a light unto my path."}, {"k": "시편 32:8", "e": "Psalm 32:8", "tk": "내가 너의 갈 길을 가르쳐 보이고 너를 주목하여 훈계하리로다", "te": "I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye."}, {"k": "이사야 30:21", "e": "Isaiah 30:21", "tk": "너희가 우편으로 치우치든지 좌편으로 치우치든지 네 뒤에서 말 소리가 네 귀에 들려 이르기를 이것이 정로니 너희는 이리로 행하라 할 것이며", "te": "And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left."}, {"k": "잠언 16:9", "e": "Proverbs 16:9", "tk": "사람이 마음으로 자기의 길을 계획할지라도 그 걸음을 인도하는 자는 여호와시니라", "te": "A man’s heart deviseth his way: but the LORD directeth his steps."}, {"k": "시편 37:23", "e": "Psalm 37:23", "tk": "여호와께서 사람의 걸음을 정하시고 그 길을 기뻐하시나니", "te": "The steps of a good man are ordered by the LORD: and he delighteth in his way."}]}, {"id": "wisdom", "ko": "지혜", "en": "Wisdom", "kw": ["지혜", "명철", "공부", "시험", "wisdom", "wise", "study", "exam"], "v": [{"k": "잠언 1:7", "e": "Proverbs 1:7", "tk": "여호와를 경외하는 것이 지식의 근본이어늘 미련한 자는 지혜와 훈계를 멸시하느니라", "te": "The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction."}, {"k": "야고보서 1:5", "e": "James 1:5", "tk": "너희 중에 누구든지 지혜가 부족하거든 모든 사람에게 후히 주시고 꾸짖지 아니하시는 하나님께 구하라 그리하면 주시리라", "te": "If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him."}, {"k": "잠언 3:13", "e": "Proverbs 3:13", "tk": "지혜를 얻은 자와 명철을 얻은 자는 복이 있나니", "te": "Happy is the man that findeth wisdom, and the man that getteth understanding."}, {"k": "잠언 9:10", "e": "Proverbs 9:10", "tk": "여호와를 경외하는 것이 지혜의 근본이요 거룩하신 자를 아는 것이 명철이니라", "te": "The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding."}, {"k": "시편 90:12", "e": "Psalm 90:12", "tk": "우리에게 우리 날 계수함을 가르치사 지혜의 마음을 얻게 하소서", "te": "So teach us to number our days, that we may apply our hearts unto wisdom."}, {"k": "잠언 4:7", "e": "Proverbs 4:7", "tk": "지혜가 제일이니 지혜를 얻으라 무릇 너의 얻은 것을 가져 명철을 얻을찌니라", "te": "Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding."}, {"k": "골로새서 3:16", "e": "Colossians 3:16", "tk": "그리스도의 말씀이 너희 속에 풍성히 거하여 모든 지혜로 피차 가르치며 권면하고 시와 찬미와 신령한 노래를 부르며 마음에 감사함으로 하나님을 찬양하고", "te": "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord."}]}, {"id": "family", "ko": "가정", "en": "Family", "kw": ["가정", "가족", "집", "family", "home", "house"], "v": [{"k": "여호수아 24:15", "e": "Joshua 24:15", "tk": "만일 여호와를 섬기는 것이 너희에게 좋지 않게 보이거든 너희 열조가 강 저편에서 섬기던 신이든지 혹 너희의 거하는 땅 아모리 사람의 신이든지 너희 섬길 자를 오늘날 택하라 오직 나와 내 집은 여호와를 섬기겠노라", "te": "And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD."}, {"k": "시편 127:1", "e": "Psalm 127:1", "tk": "여호와께서 집을 세우지 아니하시면 세우는 자의 수고가 헛되며 여호와께서 성을 지키지 아니하시면 파숫군의 경성함이 허사로다", "te": "Except the LORD build the house, they labour in vain that build it: except the LORD keep the city, the watchman waketh but in vain."}, {"k": "시편 127:3", "e": "Psalm 127:3", "tk": "자식은 여호와의 주신 기업이요 태의 열매는 그의 상급이로다", "te": "Lo, children are an heritage of the LORD: and the fruit of the womb is his reward."}, {"k": "잠언 22:6", "e": "Proverbs 22:6", "tk": "마땅히 행할 길을 아이에게 가르치라 그리하면 늙어도 그것을 떠나지 아니하리라", "te": "Train up a child in the way he should go: and when he is old, he will not depart from it."}, {"k": "에베소서 6:1", "e": "Ephesians 6:1", "tk": "자녀들아 너희 부모를 주 안에서 순종하라 이것이 옳으니라", "te": "Children, obey your parents in the Lord: for this is right."}, {"k": "출애굽기 20:12", "e": "Exodus 20:12", "tk": "네 부모를 공경하라 그리하면 너의 하나님 나 여호와가 네게 준 땅에서 네 생명이 길리라", "te": "Honour thy father and thy mother: that thy days may be long upon the land which the LORD thy God giveth thee."}, {"k": "시편 128:3", "e": "Psalm 128:3", "tk": "네 집 내실에 있는 네 아내는 결실한 포도나무 같으며 네 상에 둘린 자식은 어린 감람나무 같으리로다", "te": "Thy wife shall be as a fruitful vine by the sides of thine house: thy children like olive plants round about thy table."}, {"k": "사도행전 16:31", "e": "Acts 16:31", "tk": "가로되 주 예수를 믿으라 그리하면 너와 네 집이 구원을 얻으리라 하고", "te": "And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house."}]}, {"id": "marriage", "ko": "결혼", "en": "Marriage", "kw": ["결혼", "청첩", "부부", "신랑", "신부", "웨딩", "wedding", "marriage", "bride", "groom", "husband", "wife"], "v": [{"k": "창세기 2:24", "e": "Genesis 2:24", "tk": "이러므로 남자가 부모를 떠나 그 아내와 연합하여 둘이 한 몸을 이룰찌로다", "te": "Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh."}, {"k": "전도서 4:12", "e": "Ecclesiastes 4:12", "tk": "한 사람이면 패하겠거니와 두 사람이면 능히 당하나니 삼겹 줄은 쉽게 끊어지지 아니하느니라", "te": "And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken."}, {"k": "고린도전서 13:4", "e": "1 Corinthians 13:4", "tk": "사랑은 오래 참고 사랑은 온유하며 투기하는 자가 되지 아니하며 사랑은 자랑하지 아니하며 교만하지 아니하며", "te": "Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,"}, {"k": "골로새서 3:14", "e": "Colossians 3:14", "tk": "이 모든 것 위에 사랑을 더하라 이는 온전하게 매는 띠니라", "te": "And above all these things put on charity, which is the bond of perfectness."}, {"k": "아가 2:16", "e": "Song of Solomon 2:16", "tk": "나의 사랑하는 자는 내게 속하였고 나는 그에게 속하였구나 그가 백합화 가운데서 양떼를 먹이는구나", "te": "My beloved is mine, and I am his: he feedeth among the lilies."}, {"k": "룻기 1:16", "e": "Ruth 1:16", "tk": "룻이 가로되 나로 어머니를 떠나며 어머니를 따르지 말고 돌아가라 강권하지 마옵소서 어머니께서 가시는 곳에 나도 가고 어머니께서 유숙하시는 곳에서 나도 유숙하겠나이다 어머니의 백성이 나의 백성이 되고 어머니의 하나님이 나의 하나님이 되시리니", "te": "And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:"}, {"k": "마가복음 10:9", "e": "Mark 10:9", "tk": "그러므로 하나님이 짝지어 주신 것을 사람이 나누지 못할찌니라 하시더라", "te": "What therefore God hath joined together, let not man put asunder."}, {"k": "에베소서 5:25", "e": "Ephesians 5:25", "tk": "남편들아 아내 사랑하기를 그리스도께서 교회를 사랑하시고 위하여 자신을 주심 같이 하라", "te": "Husbands, love your wives, even as Christ also loved the church, and gave himself for it;"}]}, {"id": "baby", "ko": "아기·출산", "en": "New baby", "kw": ["아기", "출산", "태어", "돌", "백일", "임신", "baby", "birth", "newborn", "pregnancy"], "v": [{"k": "시편 139:13", "e": "Psalm 139:13", "tk": "주께서 내 장부를 지으시며 나의 모태에서 나를 조직하셨나이다", "te": "For thou hast possessed my reins: thou hast covered me in my mother’s womb."}, {"k": "시편 139:14", "e": "Psalm 139:14", "tk": "내가 주께 감사하옴은 나를 지으심이 신묘막측하심이라 주의 행사가 기이함을 내 영혼이 잘 아나이다", "te": "I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well."}, {"k": "예레미야 1:5", "e": "Jeremiah 1:5", "tk": "내가 너를 복중에 짓기 전에 너를 알았고 네가 태에서 나오기 전에 너를 구별하였고 너를 열방의 선지자로 세웠노라 하시기로", "te": "Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations."}, {"k": "시편 127:3", "e": "Psalm 127:3", "tk": "자식은 여호와의 주신 기업이요 태의 열매는 그의 상급이로다", "te": "Lo, children are an heritage of the LORD: and the fruit of the womb is his reward."}, {"k": "사무엘상 1:27", "e": "1 Samuel 1:27", "tk": "이 아이를 위하여 내가 기도하였더니 여호와께서 나의 구하여 기도한 바를 허락하신지라", "te": "For this child I prayed; and the LORD hath given me my petition which I asked of him:"}, {"k": "민수기 6:24", "e": "Numbers 6:24", "tk": "여호와는 네게 복을 주시고 너를 지키시기를 원하며", "te": "The LORD bless thee, and keep thee:"}, {"k": "마태복음 19:14", "e": "Matthew 19:14", "tk": "예수께서 가라사대 어린 아이들을 용납하고 내게 오는 것을 금하지 말라 천국이 이런 자의 것이니라 하시고", "te": "But Jesus said, Suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven."}]}, {"id": "birthday", "ko": "생일", "en": "Birthday", "kw": ["생일", "생신", "환갑", "칠순", "birthday"], "v": [{"k": "민수기 6:24", "e": "Numbers 6:24", "tk": "여호와는 네게 복을 주시고 너를 지키시기를 원하며", "te": "The LORD bless thee, and keep thee:"}, {"k": "민수기 6:25", "e": "Numbers 6:25", "tk": "여호와는 그 얼굴로 네게 비취사 은혜 베푸시기를 원하며", "te": "The LORD make his face shine upon thee, and be gracious unto thee:"}, {"k": "시편 90:12", "e": "Psalm 90:12", "tk": "우리에게 우리 날 계수함을 가르치사 지혜의 마음을 얻게 하소서", "te": "So teach us to number our days, that we may apply our hearts unto wisdom."}, {"k": "시편 118:24", "e": "Psalm 118:24", "tk": "이 날은 여호와의 정하신 것이라 이 날에 우리가 즐거워하고 기뻐하리로다", "te": "This is the day which the LORD hath made; we will rejoice and be glad in it."}, {"k": "시편 20:4", "e": "Psalm 20:4", "tk": "네 마음의 소원대로 허락하시고 네 모든 도모를 이루시기를 원하노라", "te": "Grant thee according to thine own heart, and fulfil all thy counsel."}, {"k": "시편 139:14", "e": "Psalm 139:14", "tk": "내가 주께 감사하옴은 나를 지으심이 신묘막측하심이라 주의 행사가 기이함을 내 영혼이 잘 아나이다", "te": "I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well."}, {"k": "잠언 9:11", "e": "Proverbs 9:11", "tk": "나 지혜로 말미암아 네 날이 많아질 것이요 네 생명의 해가 더하리라", "te": "For by me thy days shall be multiplied, and the years of thy life shall be increased."}]}, {"id": "graduation", "ko": "졸업·새 출발", "en": "Graduation", "kw": ["졸업", "입학", "출발", "진로", "취업", "graduation", "graduate", "career", "start"], "v": [{"k": "예레미야 29:11", "e": "Jeremiah 29:11", "tk": "나 여호와가 말하노라 너희를 향한 나의 생각은 내가 아나니 재앙이 아니라 곧 평안이요 너희 장래에 소망을 주려하는 생각이라", "te": "For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end."}, {"k": "잠언 16:3", "e": "Proverbs 16:3", "tk": "너의 행사를 여호와께 맡기라 그리하면 너의 경영하는 것이 이루리라", "te": "Commit thy works unto the LORD, and thy thoughts shall be established."}, {"k": "잠언 3:6", "e": "Proverbs 3:6", "tk": "너는 범사에 그를 인정하라 그리하면 네 길을 지도하시리라", "te": "In all thy ways acknowledge him, and he shall direct thy paths."}, {"k": "빌립보서 1:6", "e": "Philippians 1:6", "tk": "너희 속에 착한 일을 시작하신 이가 그리스도 예수의 날까지 이루실 줄을 우리가 확신하노라", "te": "Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:"}, {"k": "이사야 43:19", "e": "Isaiah 43:19", "tk": "보라 내가 새 일을 행하리니 이제 나타낼 것이라 너희가 그것을 알지 못하겠느냐 정녕히 내가 광야에 길과 사막에 강을 내리니", "te": "Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert."}, {"k": "여호수아 1:9", "e": "Joshua 1:9", "tk": "내가 네게 명한 것이 아니냐 마음을 강하게 하고 담대히 하라 두려워 말며 놀라지 말라 네가 어디로 가든지 네 하나님 여호와가 너와 함께 하느니라 하시니라", "te": "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest."}, {"k": "시편 37:4", "e": "Psalm 37:4", "tk": "또 여호와를 기뻐하라 저가 네 마음의 소원을 이루어 주시리로다", "te": "Delight thyself also in the LORD; and he shall give thee the desires of thine heart."}, {"k": "골로새서 3:23", "e": "Colossians 3:23", "tk": "무슨 일을 하든지 마음을 다하여 주께 하듯하고 사람에게 하듯하지 말라", "te": "And whatsoever ye do, do it heartily, as to the Lord, and not unto men;"}]}, {"id": "newyear", "ko": "새해", "en": "New year", "kw": ["새해", "신년", "새", "시작", "new", "year", "beginning", "fresh"], "v": [{"k": "이사야 43:18", "e": "Isaiah 43:18", "tk": "너희는 이전 일을 기억하지 말며 옛적 일을 생각하지 말라", "te": "Remember ye not the former things, neither consider the things of old."}, {"k": "이사야 43:19", "e": "Isaiah 43:19", "tk": "보라 내가 새 일을 행하리니 이제 나타낼 것이라 너희가 그것을 알지 못하겠느냐 정녕히 내가 광야에 길과 사막에 강을 내리니", "te": "Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert."}, {"k": "예레미야애가 3:22", "e": "Lamentations 3:22", "tk": "여호와의 자비와 긍휼이 무궁하시므로 우리가 진멸되지 아니함이니이다", "te": "It is of the LORD’s mercies that we are not consumed, because his compassions fail not."}, {"k": "예레미야애가 3:23", "e": "Lamentations 3:23", "tk": "이것이 아침마다 새로우니 주의 성실이 크도소이다", "te": "They are new every morning: great is thy faithfulness."}, {"k": "고린도후서 5:17", "e": "2 Corinthians 5:17", "tk": "그런즉 누구든지 그리스도 안에 있으면 새로운 피조물이라 이전 것은 지나갔으니 보라 새것이 되었도다", "te": "Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new."}, {"k": "시편 65:11", "e": "Psalm 65:11", "tk": "주의 은택으로 년사에 관 씌우시니 주의 길에는 기름이 떨어지며", "te": "Thou crownest the year with thy goodness; and thy paths drop fatness."}, {"k": "빌립보서 3:13", "e": "Philippians 3:13", "tk": "형제들아 나는 아직 내가 잡은 줄로 여기지 아니하고 오직 한 일 즉 뒤에 있는 것은 잊어버리고 앞에 있는 것을 잡으려고", "te": "Brethren, I count not myself to have apprehended: but this one thing I do, forgetting those things which are behind, and reaching forth unto those things which are before,"}, {"k": "빌립보서 3:14", "e": "Philippians 3:14", "tk": "푯대를 향하여 그리스도 예수 안에서 하나님이 위에서 부르신 부름의 상을 위하여 좇아가노라", "te": "I press toward the mark for the prize of the high calling of God in Christ Jesus."}]}, {"id": "christmas", "ko": "성탄", "en": "Christmas", "kw": ["성탄", "크리스마스", "아기예수", "christmas", "nativity"], "v": [{"k": "이사야 9:6", "e": "Isaiah 9:6", "tk": "이는 한 아기가 우리에게 났고 한 아들을 우리에게 주신바 되었는데 그 어깨에는 정사를 메었고 그 이름은 기묘자라, 모사라, 전능하신 하나님이라, 영존하시는 아버지라, 평강의 왕이라 할것임이라", "te": "For unto us a child is born, unto us a son is given: and the government shall be upon his shoulder: and his name shall be called Wonderful, Counsellor, The mighty God, The everlasting Father, The Prince of Peace."}, {"k": "누가복음 2:10", "e": "Luke 2:10", "tk": "천사가 이르되 무서워 말라 보라 내가 온 백성에게 미칠 큰 기쁨의 좋은 소식을 너희에게 전하노라", "te": "And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people."}, {"k": "누가복음 2:11", "e": "Luke 2:11", "tk": "오늘날 다윗의 동네에 너희를 위하여 구주가 나셨으니 곧 그리스도 주시니라", "te": "For unto you is born this day in the city of David a Saviour, which is Christ the Lord."}, {"k": "누가복음 2:14", "e": "Luke 2:14", "tk": "지극히 높은 곳에서는 하나님께 영광이요 땅에서는 기뻐하심을 입은 사람들 중에 평화로다 하니라", "te": "Glory to God in the highest, and on earth peace, good will toward men."}, {"k": "마태복음 1:23", "e": "Matthew 1:23", "tk": "보라 처녀가 잉태하여 아들을 낳을 것이요 그 이름은 임마누엘이라 하리라 하셨으니 이를 번역한즉 하나님이 우리와 함께 계시다 함이라", "te": "Behold, a virgin shall be with child, and shall bring forth a son, and they shall call his name Emmanuel, which being interpreted is, God with us."}, {"k": "요한복음 1:14", "e": "John 1:14", "tk": "말씀이 육신이 되어 우리 가운데 거하시매 우리가 그 영광을 보니 아버지의 독생자의 영광이요 은혜와 진리가 충만하더라", "te": "And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth."}, {"k": "요한복음 3:16", "e": "John 3:16", "tk": "하나님이 세상을 이처럼 사랑하사 독생자를 주셨으니 이는 저를 믿는 자마다 멸망치 않고 영생을 얻게 하려 하심이니라", "te": "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."}]}, {"id": "easter", "ko": "부활", "en": "Easter", "kw": ["부활", "부활절", "easter", "resurrection", "risen"], "v": [{"k": "요한복음 11:25", "e": "John 11:25", "tk": "예수께서 가라사대 나는 부활이요 생명이니 나를 믿는 자는 죽어도 살겠고", "te": "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:"}, {"k": "마태복음 28:6", "e": "Matthew 28:6", "tk": "그가 여기 계시지 않고 그의 말씀하시던대로 살아나셨느니라 와서 그의 누우셨던 곳을 보라", "te": "He is not here: for he is risen, as he said. Come, see the place where the Lord lay."}, {"k": "고린도전서 15:55", "e": "1 Corinthians 15:55", "tk": "사망아 너의 이기는 것이 어디 있느냐 사망아 너의 쏘는 것이 어디 있느냐", "te": "O death, where is thy sting? O grave, where is thy victory?"}, {"k": "고린도전서 15:57", "e": "1 Corinthians 15:57", "tk": "우리 주 예수 그리스도로 말미암아 우리에게 이김을 주시는 하나님께 감사하노니", "te": "But thanks be to God, which giveth us the victory through our Lord Jesus Christ."}, {"k": "로마서 6:4", "e": "Romans 6:4", "tk": "그러므로 우리가 그의 죽으심과 합하여 세례를 받음으로 그와 함께 장사되었나니 이는 아버지의 영광으로 말미암아 그리스도를 죽은 자 가운데서 살리심과 같이 우리로 또한 새 생명 가운데서 행하게 하려 함이니라", "te": "Therefore we are buried with him by baptism into death: that like as Christ was raised up from the dead by the glory of the Father, even so we also should walk in newness of life."}, {"k": "베드로전서 1:3", "e": "1 Peter 1:3", "tk": "찬송하리로다 우리 주 예수 그리스도의 아버지 하나님이 그 많으신 긍휼대로 예수 그리스도의 죽은 자 가운데서 부활하심으로 말미암아 우리를 거듭나게 하사 산 소망이 있게 하시며", "te": "Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead,"}]}, {"id": "healing", "ko": "치유", "en": "Healing", "kw": ["치유", "회복", "병", "아픔", "수술", "건강", "healing", "heal", "sick", "health"], "v": [{"k": "예레미야 17:14", "e": "Jeremiah 17:14", "tk": "여호와여 주는 나의 찬송이시오니 나를 고치소서 그리하시면 내가 낫겠나이다 나를 구원하소서 그리하시면 내가 구원을 얻으리이다", "te": "Heal me, O LORD, and I shall be healed; save me, and I shall be saved: for thou art my praise."}, {"k": "시편 103:2", "e": "Psalm 103:2", "tk": "내 영혼아 여호와를 송축하며 그 모든 은택을 잊지 말찌어다", "te": "Bless the LORD, O my soul, and forget not all his benefits:"}, {"k": "시편 103:3", "e": "Psalm 103:3", "tk": "저가 네 모든 죄악을 사하시며 네 모든 병을 고치시며", "te": "Who forgiveth all thine iniquities; who healeth all thy diseases;"}, {"k": "시편 147:3", "e": "Psalm 147:3", "tk": "상심한 자를 고치시며 저희 상처를 싸매시는도다", "te": "He healeth the broken in heart, and bindeth up their wounds."}, {"k": "이사야 53:5", "e": "Isaiah 53:5", "tk": "그가 찔림은 우리의 허물을 인함이요 그가 상함은 우리의 죄악을 인함이라 그가 징계를 받음으로 우리가 평화를 누리고 그가 채찍에 맞음으로 우리가 나음을 입었도다", "te": "But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed."}, {"k": "출애굽기 15:26", "e": "Exodus 15:26", "tk": "가라사대 너희가 너희 하나님 나 여호와의 말을 청종하고 나의 보기에 의를 행하며 내 계명에 귀를 기울이며 내 모든 규례를 지키면 내가 애굽 사람에게 내린 모든 질병의 하나도 너희에게 내리지 아니하리니 나는 너희를 치료하는 여호와임이니라", "te": "And said, If thou wilt diligently hearken to the voice of the LORD thy God, and wilt do that which is right in his sight, and wilt give ear to his commandments, and keep all his statutes, I will put none of these diseases upon thee, which I have brought upon the Egyptians: for I am the LORD that healeth thee."}, {"k": "야고보서 5:15", "e": "James 5:15", "tk": "믿음의 기도는 병든 자를 구원하리니 주께서 저를 일으키시리라 혹시 죄를 범하였을찌라도 사하심을 얻으리라", "te": "And the prayer of faith shall save the sick, and the Lord shall raise him up; and if he have committed sins, they shall be forgiven him."}]}, {"id": "fear", "ko": "두려움", "en": "Fear", "kw": ["두려", "무서", "불안", "fear", "afraid", "scared"], "v": [{"k": "이사야 41:10", "e": "Isaiah 41:10", "tk": "두려워 말라 내가 너와 함께 함이니라 놀라지 말라 나는 네 하나님이 됨이니라 내가 너를 굳세게 하리라 참으로 너를 도와 주리라 참으로 나의 의로운 오른손으로 너를 붙들리라", "te": "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness."}, {"k": "시편 23:4", "e": "Psalm 23:4", "tk": "내가 사망의 음침한 골짜기로 다닐찌라도 해를 두려워하지 않을 것은 주께서 나와 함께 하심이라 주의 지팡이와 막대기가 나를 안위하시나이다", "te": "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me."}, {"k": "시편 27:1", "e": "Psalm 27:1", "tk": "여호와는 나의 빛이요 나의 구원이시니 내가 누구를 두려워하리요 여호와는 내 생명의 능력이시니 내가 누구를 무서워하리요", "te": "The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?"}, {"k": "시편 56:3", "e": "Psalm 56:3", "tk": "내가 두려워하는 날에는 주를 의지하리이다", "te": "What time I am afraid, I will trust in thee."}, {"k": "디모데후서 1:7", "e": "2 Timothy 1:7", "tk": "하나님이 우리에게 주신 것은 두려워하는 마음이 아니요 오직 능력과 사랑과 근신하는 마음이니", "te": "For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind."}, {"k": "요한복음 14:27", "e": "John 14:27", "tk": "평안을 너희에게 끼치노니 곧 나의 평안을 너희에게 주노라 내가 너희에게 주는 것은 세상이 주는 것 같지 아니하니라 너희는 마음에 근심도 말고 두려워하지도 말라", "te": "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid."}, {"k": "시편 34:4", "e": "Psalm 34:4", "tk": "내가 여호와께 구하매 내게 응답하시고 내 모든 두려움에서 나를 건지셨도다", "te": "I sought the LORD, and he heard me, and delivered me from all my fears."}, {"k": "요한일서 4:18", "e": "1 John 4:18", "tk": "사랑 안에 두려움이 없고 온전한 사랑이 두려움을 내어 쫓나니 두려움에는 형벌이 있음이라 두려워하는 자는 사랑 안에서 온전히 이루지 못하였느니라", "te": "There is no fear in love; but perfect love casteth out fear: because fear hath torment. He that feareth is not made perfect in love."}]}, {"id": "forgiveness", "ko": "용서", "en": "Forgiveness", "kw": ["용서", "죄", "회개", "forgive", "forgiveness", "sin"], "v": [{"k": "요한일서 1:9", "e": "1 John 1:9", "tk": "만일 우리가 우리 죄를 자백하면 저는 미쁘시고 의로우사 우리 죄를 사하시며 모든 불의에서 우리를 깨끗케 하실 것이요", "te": "If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness."}, {"k": "에베소서 4:32", "e": "Ephesians 4:32", "tk": "서로 인자하게 하며 불쌍히 여기며 서로 용서하기를 하나님이 그리스도 안에서 너희를 용서하심과 같이 하라", "te": "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you."}, {"k": "골로새서 3:13", "e": "Colossians 3:13", "tk": "누가 뉘게 혐의가 있거든 서로 용납하여 피차 용서하되 주께서 너희를 용서하신 것과 같이 너희도 그리하고", "te": "Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye."}, {"k": "마태복음 6:14", "e": "Matthew 6:14", "tk": "너희가 사람의 과실을 용서하면 너희 천부께서도 너희 과실을 용서하시려니와", "te": "For if ye forgive men their trespasses, your heavenly Father will also forgive you:"}, {"k": "시편 103:12", "e": "Psalm 103:12", "tk": "동이 서에서 먼 것 같이 우리 죄과를 우리에게서 멀리 옮기셨으며", "te": "As far as the east is from the west, so far hath he removed our transgressions from us."}, {"k": "이사야 1:18", "e": "Isaiah 1:18", "tk": "여호와께서 말씀하시되 오라 우리가 서로 변론하자 너희 죄가 주홍 같을찌라도 눈과 같이 희어질 것이요 진홍 같이 붉을찌라도 양털 같이 되리라", "te": "Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool."}, {"k": "미가 7:18", "e": "Micah 7:18", "tk": "주와 같은 신이 어디 있으리이까 주께서는 죄악을 사유하시며 그 기업의 남은 자의 허물을 넘기시며 인애를 기뻐하심으로 노를 항상 품지 아니하시나이다", "te": "Who is a God like unto thee, that pardoneth iniquity, and passeth by the transgression of the remnant of his heritage? he retaineth not his anger for ever, because he delighteth in mercy."}]}, {"id": "grace", "ko": "은혜", "en": "Grace", "kw": ["은혜", "은총", "grace"], "v": [{"k": "에베소서 2:8", "e": "Ephesians 2:8", "tk": "너희가 그 은혜를 인하여 믿음으로 말미암아 구원을 얻었나니 이것이 너희에게서 난 것이 아니요 하나님의 선물이라", "te": "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:"}, {"k": "고린도후서 12:9", "e": "2 Corinthians 12:9", "tk": "내게 이르시기를 내 은혜가 네게 족하도다 이는 내 능력이 약한데서 온전하여짐이라 하신지라 이러므로 도리어 크게 기뻐함으로 나의 여러 약한 것들에 대하여 자랑하리니 이는 그리스도의 능력으로 내게 머물게 하려함이라", "te": "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me."}, {"k": "요한복음 1:16", "e": "John 1:16", "tk": "우리가 다 그의 충만한데서 받으니 은혜 위에 은혜러라", "te": "And of his fulness have all we received, and grace for grace."}, {"k": "히브리서 4:16", "e": "Hebrews 4:16", "tk": "그러므로 우리가 긍휼하심을 받고 때를 따라 돕는 은혜를 얻기 위하여 은혜의 보좌 앞에 담대히 나아갈 것이니라", "te": "Let us therefore come boldly unto the throne of grace, that we may obtain mercy, and find grace to help in time of need."}, {"k": "로마서 3:24", "e": "Romans 3:24", "tk": "그리스도 예수 안에 있는 구속으로 말미암아 하나님의 은혜로 값 없이 의롭다 하심을 얻은 자 되었느니라", "te": "Being justified freely by his grace through the redemption that is in Christ Jesus:"}, {"k": "민수기 6:25", "e": "Numbers 6:25", "tk": "여호와는 그 얼굴로 네게 비취사 은혜 베푸시기를 원하며", "te": "The LORD make his face shine upon thee, and be gracious unto thee:"}, {"k": "디도서 2:11", "e": "Titus 2:11", "tk": "모든 사람에게 구원을 주시는 하나님의 은혜가 나타나", "te": "For the grace of God that bringeth salvation hath appeared to all men,"}]}, {"id": "creation", "ko": "자연·창조", "en": "Nature", "kw": ["자연", "창조", "하늘", "산", "별", "바다", "꽃", "nature", "creation", "sky", "mountain", "stars", "sea"], "v": [{"k": "창세기 1:1", "e": "Genesis 1:1", "tk": "태초에 하나님이 천지를 창조하시니라", "te": "In the beginning God created the heaven and the earth."}, {"k": "시편 19:1", "e": "Psalm 19:1", "tk": "하늘이 하나님의 영광을 선포하고 궁창이 그 손으로 하신 일을 나타내는도다", "te": "The heavens declare the glory of God; and the firmament sheweth his handywork."}, {"k": "시편 24:1", "e": "Psalm 24:1", "tk": "땅과 거기 충만한 것과 세계와 그 중에 거하는 자가 다 여호와의 것이로다", "te": "The earth is the LORD’s, and the fulness thereof; the world, and they that dwell therein."}, {"k": "시편 104:24", "e": "Psalm 104:24", "tk": "여호와여 주의 하신 일이 어찌 그리 많은지요 주께서 지혜로 저희를 다 지으셨으니 주의 부요가 땅에 가득하니이다", "te": "O LORD, how manifold are thy works! in wisdom hast thou made them all: the earth is full of thy riches."}, {"k": "시편 8:3", "e": "Psalm 8:3", "tk": "주의 손가락으로 만드신 주의 하늘과 주의 베풀어 두신 달과 별들을 내가 보오니", "te": "When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained;"}, {"k": "창세기 1:31", "e": "Genesis 1:31", "tk": "하나님이 그 지으신 모든 것을 보시니 보시기에 심히 좋았더라 저녁이 되며 아침이 되니 이는 여섯째 날이니라", "te": "And God saw every thing that he had made, and, behold, it was very good. And the evening and the morning were the sixth day."}, {"k": "이사야 40:8", "e": "Isaiah 40:8", "tk": "풀은 마르고 꽃은 시드나 우리 하나님의 말씀은 영영히 서리라 하라", "te": "The grass withereth, the flower fadeth: but the word of our God shall stand for ever."}, {"k": "시편 121:1", "e": "Psalm 121:1", "tk": "내가 산을 향하여 눈을 들리라 나의 도움이 어디서 올꼬", "te": "I will lift up mine eyes unto the hills, from whence cometh my help."}, {"k": "시편 121:2", "e": "Psalm 121:2", "tk": "나의 도움이 천지를 지으신 여호와에게서로다", "te": "My help cometh from the LORD, which made heaven and earth."}]}, {"id": "rest", "ko": "쉼", "en": "Rest", "kw": ["쉼", "쉬", "휴식", "안식", "피곤", "rest", "tired", "sabbath"], "v": [{"k": "마태복음 11:28", "e": "Matthew 11:28", "tk": "수고하고 무거운 짐진 자들아 다 내게로 오라 내가 너희를 쉬게 하리라", "te": "Come unto me, all ye that labour and are heavy laden, and I will give you rest."}, {"k": "마태복음 11:29", "e": "Matthew 11:29", "tk": "나는 마음이 온유하고 겸손하니 나의 멍에를 메고 내게 배우라 그러면 너희 마음이 쉼을 얻으리니", "te": "Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls."}, {"k": "시편 23:2", "e": "Psalm 23:2", "tk": "그가 나를 푸른 초장에 누이시며 쉴만한 물 가으로 인도하시는도다", "te": "He maketh me to lie down in green pastures: he leadeth me beside the still waters."}, {"k": "시편 62:1", "e": "Psalm 62:1", "tk": "나의 영혼이 잠잠히 하나님만 바람이여 나의 구원이 그에게서 나는도다", "te": "Truly my soul waiteth upon God: from him cometh my salvation."}, {"k": "시편 46:10", "e": "Psalm 46:10", "tk": "이르시기를 너희는 가만히 있어 내가 하나님 됨을 알찌어다 내가 열방과 세계 중에서 높임을 받으리라 하시도다", "te": "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth."}, {"k": "출애굽기 33:14", "e": "Exodus 33:14", "tk": "여호와께서 가라사대 내가 친히 가리라 내가 너로 편케 하리라", "te": "And he said, My presence shall go with thee, and I will give thee rest."}, {"k": "이사야 30:15", "e": "Isaiah 30:15", "tk": "주 여호와 이스라엘의 거룩하신 자가 말씀하시되 너희가 돌이켜 안연히 처하여야 구원을 얻을 것이요 잠잠하고 신뢰하여야 힘을 얻을 것이어늘 너희가 원치 아니하고", "te": "For thus saith the Lord GOD, the Holy One of Israel; In returning and rest shall ye be saved; in quietness and in confidence shall be your strength: and ye would not."}]}, {"id": "work", "ko": "일·직장", "en": "Work", "kw": ["일", "직장", "사업", "개업", "work", "job", "business", "office"], "v": [{"k": "골로새서 3:23", "e": "Colossians 3:23", "tk": "무슨 일을 하든지 마음을 다하여 주께 하듯하고 사람에게 하듯하지 말라", "te": "And whatsoever ye do, do it heartily, as to the Lord, and not unto men;"}, {"k": "잠언 16:3", "e": "Proverbs 16:3", "tk": "너의 행사를 여호와께 맡기라 그리하면 너의 경영하는 것이 이루리라", "te": "Commit thy works unto the LORD, and thy thoughts shall be established."}, {"k": "시편 90:17", "e": "Psalm 90:17", "tk": "주 우리 하나님의 은총을 우리에게 임하게 하사 우리 손의 행사를 우리에게 견고케 하소서 우리 손의 행사를 견고케 하소서", "te": "And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it."}, {"k": "고린도전서 15:58", "e": "1 Corinthians 15:58", "tk": "그러므로 내 사랑 하는 형제들아 견고하며 흔들리지 말며 항상 주의 일에 더욱 힘쓰는 자들이 되라 이는 너희 수고가 주 안에서 헛되지 않은 줄을 앎이니라", "te": "Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord."}, {"k": "전도서 9:10", "e": "Ecclesiastes 9:10", "tk": "무릇 네 손이 일을 당하는대로 힘을 다하여 할찌어다 네가 장차 들어갈 음부에는 일도 없고 계획도 없고 지식도 없고 지혜도 없음이니라", "te": "Whatsoever thy hand findeth to do, do it with thy might; for there is no work, nor device, nor knowledge, nor wisdom, in the grave, whither thou goest."}, {"k": "잠언 22:29", "e": "Proverbs 22:29", "tk": "네가 자기 사업에 근실한 사람을 보았느냐 이러한 사람은 왕 앞에 설 것이요 천한 자 앞에 서지 아니하리라", "te": "Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men."}, {"k": "갈라디아서 6:9", "e": "Galatians 6:9", "tk": "우리가 선을 행하되 낙심하지 말찌니 피곤하지 아니하면 때가 이르매 거두리라", "te": "And let us not be weary in well doing: for in due season we shall reap, if we faint not."}]}, {"id": "friend", "ko": "친구", "en": "Friendship", "kw": ["친구", "우정", "동료", "friend", "friendship"], "v": [{"k": "잠언 17:17", "e": "Proverbs 17:17", "tk": "친구는 사랑이 끊이지 아니하고 형제는 위급한 때까지 위하여 났느니라", "te": "A friend loveth at all times, and a brother is born for adversity."}, {"k": "요한복음 15:13", "e": "John 15:13", "tk": "사람이 친구를 위하여 자기 목숨을 버리면 이에서 더 큰 사랑이 없나니", "te": "Greater love hath no man than this, that a man lay down his life for his friends."}, {"k": "잠언 27:17", "e": "Proverbs 27:17", "tk": "철이 철을 날카롭게 하는 것 같이 사람이 그 친구의 얼굴을 빛나게 하느니라", "te": "Iron sharpeneth iron; so a man sharpeneth the countenance of his friend."}, {"k": "전도서 4:9", "e": "Ecclesiastes 4:9", "tk": "두 사람이 한 사람보다 나음은 저희가 수고함으로 좋은 상을 얻을 것임이라", "te": "Two are better than one; because they have a good reward for their labour."}, {"k": "전도서 4:10", "e": "Ecclesiastes 4:10", "tk": "혹시 저희가 넘어지면 하나가 그 동무를 붙들어 일으키려니와 홀로 있어 넘어지고 붙들어 일으킬 자가 없는 자에게는 화가 있으리라", "te": "For if they fall, the one will lift up his fellow: but woe to him that is alone when he falleth; for he hath not another to help him up."}, {"k": "잠언 18:24", "e": "Proverbs 18:24", "tk": "많은 친구를 얻는 자는 해를 당하게 되거니와 어떤 친구는 형제보다 친밀하니라", "te": "A man that hath friends must shew himself friendly: and there is a friend that sticketh closer than a brother."}, {"k": "데살로니가전서 5:11", "e": "1 Thessalonians 5:11", "tk": "그러므로 피차 권면하고 피차 덕을 세우기를 너희가 하는것 같이 하라", "te": "Wherefore comfort yourselves together, and edify one another, even as also ye do."}]}, {"id": "praise", "ko": "찬양", "en": "Praise", "kw": ["찬양", "찬송", "예배", "노래", "praise", "worship", "song", "sing"], "v": [{"k": "시편 150:6", "e": "Psalm 150:6", "tk": "호흡이 있는 자마다 여호와를 찬양할찌어다 할렐루야", "te": "Let every thing that hath breath praise the LORD. Praise ye the LORD."}, {"k": "시편 103:1", "e": "Psalm 103:1", "tk": "내 영혼아 여호와를 송축하라 내 속에 있는 것들아 다 그 성호를 송축하라", "te": "Bless the LORD, O my soul: and all that is within me, bless his holy name."}, {"k": "시편 34:1", "e": "Psalm 34:1", "tk": "내가 여호와를 항상 송축함이여 그를 송축함이 내 입에 계속하리로다", "te": "I will bless the LORD at all times: his praise shall continually be in my mouth."}, {"k": "시편 100:1", "e": "Psalm 100:1", "tk": "온 땅이여 여호와께 즐거이 부를찌어다", "te": "Make a joyful noise unto the LORD, all ye lands."}, {"k": "시편 100:2", "e": "Psalm 100:2", "tk": "기쁨으로 여호와를 섬기며 노래하면서 그 앞에 나아갈찌어다", "te": "Serve the LORD with gladness: come before his presence with singing."}, {"k": "시편 95:1", "e": "Psalm 95:1", "tk": "오라 우리가 여호와께 노래하며 우리 구원의 반석을 향하여 즐거이 부르자", "te": "O come, let us sing unto the LORD: let us make a joyful noise to the rock of our salvation."}, {"k": "시편 113:3", "e": "Psalm 113:3", "tk": "해 돋는데서부터 해 지는데까지 여호와의 이름이 찬양을 받으시리로다", "te": "From the rising of the sun unto the going down of the same the LORD’s name is to be praised."}, {"k": "시편 146:2", "e": "Psalm 146:2", "tk": "나의 생전에 여호와를 찬양하며 나의 평생에 내 하나님을 찬송하리로다", "te": "While I live will I praise the LORD: I will sing praises unto my God while I have any being."}]}, {"id": "salvation", "ko": "구원", "en": "Salvation", "kw": ["구원", "영생", "십자가", "salvation", "saved", "eternal", "cross"], "v": [{"k": "요한복음 3:16", "e": "John 3:16", "tk": "하나님이 세상을 이처럼 사랑하사 독생자를 주셨으니 이는 저를 믿는 자마다 멸망치 않고 영생을 얻게 하려 하심이니라", "te": "For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life."}, {"k": "로마서 10:9", "e": "Romans 10:9", "tk": "네가 만일 네 입으로 예수를 주로 시인하며 또 하나님께서 그를 죽은 자 가운데서 살리신 것을 네 마음에 믿으면 구원을 얻으리니", "te": "That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved."}, {"k": "사도행전 16:31", "e": "Acts 16:31", "tk": "가로되 주 예수를 믿으라 그리하면 너와 네 집이 구원을 얻으리라 하고", "te": "And they said, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house."}, {"k": "에베소서 2:8", "e": "Ephesians 2:8", "tk": "너희가 그 은혜를 인하여 믿음으로 말미암아 구원을 얻었나니 이것이 너희에게서 난 것이 아니요 하나님의 선물이라", "te": "For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:"}, {"k": "로마서 6:23", "e": "Romans 6:23", "tk": "죄의 삯은 사망이요 하나님의 은사는 그리스도 예수 우리 주 안에 있는 영생이니라", "te": "For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord."}, {"k": "요한복음 14:6", "e": "John 14:6", "tk": "예수께서 가라사대 내가 곧 길이요 진리요 생명이니 나로 말미암지 않고는 아버지께로 올 자가 없느니라", "te": "Jesus saith unto him, I am the way, the truth, and the life: no man cometh unto the Father, but by me."}, {"k": "로마서 5:8", "e": "Romans 5:8", "tk": "우리가 아직 죄인 되었을 때에 그리스도께서 우리를 위하여 죽으심으로 하나님께서 우리에게 대한 자기의 사랑을 확증하셨느니라", "te": "But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us."}]}, {"id": "light", "ko": "빛", "en": "Light", "kw": ["빛", "등불", "어둠", "light", "lamp", "darkness"], "v": [{"k": "요한복음 8:12", "e": "John 8:12", "tk": "예수께서 또 일러 가라사대 나는 세상의 빛이니 나를 따르는 자는 어두움에 다니지 아니하고 생명의 빛을 얻으리라", "te": "Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life."}, {"k": "마태복음 5:14", "e": "Matthew 5:14", "tk": "너희는 세상의 빛이라 산위에 있는 동네가 숨기우지 못할 것이요", "te": "Ye are the light of the world. A city that is set on an hill cannot be hid."}, {"k": "마태복음 5:16", "e": "Matthew 5:16", "tk": "이같이 너희 빛을 사람 앞에 비취게 하여 저희로 너희 착한 행실을 보고 하늘에 계신 너희 아버지께 영광을 돌리게 하라", "te": "Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven."}, {"k": "시편 119:105", "e": "Psalm 119:105", "tk": "주의 말씀은 내 발에 등이요 내 길에 빛이니이다", "te": "Thy word is a lamp unto my feet, and a light unto my path."}, {"k": "시편 27:1", "e": "Psalm 27:1", "tk": "여호와는 나의 빛이요 나의 구원이시니 내가 누구를 두려워하리요 여호와는 내 생명의 능력이시니 내가 누구를 무서워하리요", "te": "The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?"}, {"k": "요한일서 1:5", "e": "1 John 1:5", "tk": "우리가 저에게서 듣고 너희에게 전하는 소식이 이것이니 곧 하나님은 빛이시라 그에게는 어두움이 조금도 없으시니라", "te": "This then is the message which we have heard of him, and declare unto you, that God is light, and in him is no darkness at all."}, {"k": "이사야 60:1", "e": "Isaiah 60:1", "tk": "일어나라 빛을 발하라 이는 네 빛이 이르렀고 여호와의 영광이 네 위에 임하였음이니라", "te": "Arise, shine; for thy light is come, and the glory of the LORD is risen upon thee."}, {"k": "요한복음 1:5", "e": "John 1:5", "tk": "빛이 어두움에 비취되 어두움이 깨닫지 못하더라", "te": "And the light shineth in darkness; and the darkness comprehended it not."}]}, {"id": "blessing", "ko": "축복", "en": "Blessing", "kw": ["축복", "복", "blessing", "bless", "blessed"], "v": [{"k": "민수기 6:24", "e": "Numbers 6:24", "tk": "여호와는 네게 복을 주시고 너를 지키시기를 원하며", "te": "The LORD bless thee, and keep thee:"}, {"k": "민수기 6:25", "e": "Numbers 6:25", "tk": "여호와는 그 얼굴로 네게 비취사 은혜 베푸시기를 원하며", "te": "The LORD make his face shine upon thee, and be gracious unto thee:"}, {"k": "민수기 6:26", "e": "Numbers 6:26", "tk": "여호와는 그 얼굴을 네게로 향하여 드사 평강 주시기를 원하노라 할찌니라 하라", "te": "The LORD lift up his countenance upon thee, and give thee peace."}, {"k": "시편 1:1", "e": "Psalm 1:1", "tk": "복 있는 사람은 악인의 꾀를 좇지 아니하며 죄인의 길에 서지 아니하며 오만한 자의 자리에 앉지 아니하고", "te": "Blessed is the man that walketh not in the counsel of the ungodly, nor standeth in the way of sinners, nor sitteth in the seat of the scornful."}, {"k": "시편 1:3", "e": "Psalm 1:3", "tk": "저는 시냇가에 심은 나무가 시절을 좇아 과실을 맺으며 그 잎사귀가 마르지 아니함 같으니 그 행사가 다 형통하리로다", "te": "And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper."}, {"k": "예레미야 17:7", "e": "Jeremiah 17:7", "tk": "그러나 무릇 여호와를 의지하며 여호와를 의뢰하는 그 사람은 복을 받을 것이라", "te": "Blessed is the man that trusteth in the LORD, and whose hope the LORD is."}, {"k": "마태복음 5:3", "e": "Matthew 5:3", "tk": "심령이 가난한 자는 복이 있나니 천국이 저희 것임이요", "te": "Blessed are the poor in spirit: for theirs is the kingdom of heaven."}, {"k": "시편 37:4", "e": "Psalm 37:4", "tk": "또 여호와를 기뻐하라 저가 네 마음의 소원을 이루어 주시리로다", "te": "Delight thyself also in the LORD; and he shall give thee the desires of thine heart."}, {"k": "요한삼서 1:2", "e": "3 John 1:2", "tk": "사랑하는 자여 네 영혼이 잘 됨같이 네가 범사에 잘 되고 강건하기를 내가 간구하노라", "te": "Beloved, I wish above all things that thou mayest prosper and be in health, even as thy soul prospereth."}]}, {"id": "humility", "ko": "겸손·섬김", "en": "Humility", "kw": ["겸손", "섬김", "봉사", "humble", "humility", "serve", "service"], "v": [{"k": "미가 6:8", "e": "Micah 6:8", "tk": "사람아 주께서 선한 것이 무엇임을 네게 보이셨나니 여호와께서 네게 구하시는 것이 오직 공의를 행하며 인자를 사랑하며 겸손히 네 하나님과 함께 행하는 것이 아니냐", "te": "He hath shewed thee, O man, what is good; and what doth the LORD require of thee, but to do justly, and to love mercy, and to walk humbly with thy God?"}, {"k": "빌립보서 2:3", "e": "Philippians 2:3", "tk": "아무 일에든지 다툼이나 허영으로 하지 말고 오직 겸손한 마음으로 각각 자기보다 남을 낫게 여기고", "te": "Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves."}, {"k": "마가복음 10:45", "e": "Mark 10:45", "tk": "인자의 온 것은 섬김을 받으려 함이 아니라 도리어 섬기려 하고 자기 목숨을 많은 사람의 대속물로 주려 함이니라", "te": "For even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many."}, {"k": "갈라디아서 5:13", "e": "Galatians 5:13", "tk": "형제들아 너희가 자유를 위하여 부르심을 입었으나 그러나 그 자유로 육체의 기회를 삼지 말고 오직 사랑으로 서로 종노릇하라", "te": "For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another."}, {"k": "야고보서 4:10", "e": "James 4:10", "tk": "주 앞에서 낮추라 그리하면 주께서 너희를 높이시리라", "te": "Humble yourselves in the sight of the Lord, and he shall lift you up."}, {"k": "마태복음 5:5", "e": "Matthew 5:5", "tk": "온유한 자는 복이 있나니 저희가 땅을 기업으로 받을 것임이요", "te": "Blessed are the meek: for they shall inherit the earth."}, {"k": "베드로전서 5:5", "e": "1 Peter 5:5", "tk": "젊은 자들아 이와 같이 장로들에게 순복하고 다 서로 겸손으로 허리를 동이라 하나님이 교만한 자를 대적하시되 겸손한 자들에게는 은혜를 주시느니라", "te": "Likewise, ye younger, submit yourselves unto the elder. Yea, all of you be subject one to another, and be clothed with humility: for God resisteth the proud, and giveth grace to the humble."}]}, {"id": "patience", "ko": "인내", "en": "Patience", "kw": ["인내", "기다", "참", "patience", "wait", "endure"], "v": [{"k": "로마서 12:12", "e": "Romans 12:12", "tk": "소망 중에 즐거워하며 환난 중에 참으며 기도에 항상 힘쓰며", "te": "Rejoicing in hope; patient in tribulation; continuing instant in prayer;"}, {"k": "갈라디아서 6:9", "e": "Galatians 6:9", "tk": "우리가 선을 행하되 낙심하지 말찌니 피곤하지 아니하면 때가 이르매 거두리라", "te": "And let us not be weary in well doing: for in due season we shall reap, if we faint not."}, {"k": "야고보서 1:4", "e": "James 1:4", "tk": "인내를 온전히 이루라 이는 너희로 온전하고 구비하여 조금도 부족함이 없게 하려 함이라", "te": "But let patience have her perfect work, that ye may be perfect and entire, wanting nothing."}, {"k": "시편 27:14", "e": "Psalm 27:14", "tk": "너는 여호와를 바랄찌어다 강하고 담대하며 여호와를 바랄찌어다", "te": "Wait on the LORD: be of good courage, and he shall strengthen thine heart: wait, I say, on the LORD."}, {"k": "시편 37:7", "e": "Psalm 37:7", "tk": "여호와 앞에 잠잠하고 참아 기다리라 자기 길이 형통하며 악한 꾀를 이루는 자를 인하여 불평하여 말지어다", "te": "Rest in the LORD, and wait patiently for him: fret not thyself because of him who prospereth in his way, because of the man who bringeth wicked devices to pass."}, {"k": "히브리서 12:1", "e": "Hebrews 12:1", "tk": "이러므로 우리에게 구름 같이 둘러싼 허다한 증인들이 있으니 모든 무거운 것과 얽매이기 쉬운 죄를 벗어 버리고 인내로써 우리 앞에 당한 경주를 경주하며", "te": "Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us,"}, {"k": "이사야 40:31", "e": "Isaiah 40:31", "tk": "오직 여호와를 앙망하는 자는 새 힘을 얻으리니 독수리의 날개치며 올라감 같을 것이요 달음박질하여도 곤비치 아니하겠고 걸어가도 피곤치 아니하리로다", "te": "But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint."}]}, {"id": "church", "ko": "교회·예배", "en": "Church", "kw": ["교회", "예배", "주일", "church", "worship", "sunday", "fellowship"], "v": [{"k": "시편 122:1", "e": "Psalm 122:1", "tk": "사람이 내게 말하기를 여호와의 집에 올라가자 할 때에 내가 기뻐하였도다", "te": "I was glad when they said unto me, Let us go into the house of the LORD."}, {"k": "히브리서 10:25", "e": "Hebrews 10:25", "tk": "모이기를 폐하는 어떤 사람들의 습관과 같이 하지 말고 오직 권하여 그날이 가까움을 볼수록 더욱 그리하자", "te": "Not forsaking the assembling of ourselves together, as the manner of some is; but exhorting one another: and so much the more, as ye see the day approaching."}, {"k": "마태복음 18:20", "e": "Matthew 18:20", "tk": "두 세 사람이 내 이름으로 모인 곳에는 나도 그들 중에 있느니라", "te": "For where two or three are gathered together in my name, there am I in the midst of them."}, {"k": "시편 84:10", "e": "Psalm 84:10", "tk": "주의 궁정에서 한 날이 다른 곳에서 천날보다 나은즉 악인의 장막에 거함보다 내 하나님 문지기로 있는 것이 좋사오니", "te": "For a day in thy courts is better than a thousand. I had rather be a doorkeeper in the house of my God, than to dwell in the tents of wickedness."}, {"k": "요한복음 4:24", "e": "John 4:24", "tk": "하나님은 영이시니 예배하는 자가 신령과 진정으로 예배할찌니라", "te": "God is a Spirit: and they that worship him must worship him in spirit and in truth."}, {"k": "사도행전 2:42", "e": "Acts 2:42", "tk": "저희가 사도의 가르침을 받아 서로 교제하며 떡을 떼며 기도하기를 전혀 힘쓰니라", "te": "And they continued stedfastly in the apostles’ doctrine and fellowship, and in breaking of bread, and in prayers."}, {"k": "시편 133:1", "e": "Psalm 133:1", "tk": "형제가 연합하여 동거함이 어찌 그리 선하고 아름다운고", "te": "Behold, how good and how pleasant it is for brethren to dwell together in unity!"}]}, {"id": "grief", "ko": "슬픔·애도", "en": "Grief", "kw": ["슬픔", "애도", "장례", "이별", "그리움", "grief", "loss", "funeral", "mourning"], "v": [{"k": "시편 34:18", "e": "Psalm 34:18", "tk": "여호와는 마음이 상한 자에게 가까이 하시고 중심에 통회하는 자를 구원하시는도다", "te": "The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit."}, {"k": "마태복음 5:4", "e": "Matthew 5:4", "tk": "애통하는 자는 복이 있나니 저희가 위로를 받을 것임이요", "te": "Blessed are they that mourn: for they shall be comforted."}, {"k": "요한계시록 21:4", "e": "Revelation 21:4", "tk": "모든 눈물을 그 눈에서 씻기시매 다시 사망이 없고 애통하는 것이나 곡하는 것이나 아픈 것이 다시 있지 아니하리니 처음 것들이 다 지나갔음이러라", "te": "And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away."}, {"k": "요한복음 11:25", "e": "John 11:25", "tk": "예수께서 가라사대 나는 부활이요 생명이니 나를 믿는 자는 죽어도 살겠고", "te": "Jesus said unto her, I am the resurrection, and the life: he that believeth in me, though he were dead, yet shall he live:"}, {"k": "시편 30:5", "e": "Psalm 30:5", "tk": "그 노염은 잠간이요 그 은총은 평생이로다 저녁에는 울음이 기숙할찌라도 아침에는 기쁨이 오리로다", "te": "For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning."}, {"k": "요한복음 16:22", "e": "John 16:22", "tk": "지금은 너희가 근심하나 내가 다시 너희를 보리니 너희 마음이 기쁠 것이요 너희 기쁨을 빼앗을 자가 없느니라", "te": "And ye now therefore have sorrow: but I will see you again, and your heart shall rejoice, and your joy no man taketh from you."}, {"k": "고린도후서 4:17", "e": "2 Corinthians 4:17", "tk": "우리의 잠시 받는 환난의 경한 것이 지극히 크고 영원한 영광의 중한 것을 우리에게 이루게 함이니", "te": "For our light affliction, which is but for a moment, worketh for us a far more exceeding and eternal weight of glory;"}]}, {"id": "anxiety", "ko": "걱정·근심", "en": "Worry", "kw": ["걱정", "근심", "염려", "불안", "worry", "anxiety", "anxious"], "v": [{"k": "빌립보서 4:6", "e": "Philippians 4:6", "tk": "아무 것도 염려하지 말고 오직 모든 일에 기도와 간구로, 너희 구할 것을 감사함으로 하나님께 아뢰라", "te": "Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God."}, {"k": "베드로전서 5:7", "e": "1 Peter 5:7", "tk": "너희 염려를 다 주께 맡겨 버리라 이는 저가 너희를 권고하심이니라", "te": "Casting all your care upon him; for he careth for you."}, {"k": "마태복음 6:34", "e": "Matthew 6:34", "tk": "그러므로 내일 일을 위하여 염려하지 말라 내일 일은 내일 염려할 것이요 한 날 괴로움은 그 날에 족하니라", "te": "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof."}, {"k": "시편 55:22", "e": "Psalm 55:22", "tk": "네 짐을 여호와께 맡겨 버리라 너를 붙드시고 의인의 요동함을 영영히 허락지 아니하시리로다", "te": "Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved."}, {"k": "요한복음 14:1", "e": "John 14:1", "tk": "너희는 마음에 근심하지 말라 하나님을 믿으니 또 나를 믿으라", "te": "Let not your heart be troubled: ye believe in God, believe also in me."}, {"k": "마태복음 6:26", "e": "Matthew 6:26", "tk": "공중의 새를 보라 심지도 않고 거두지도 않고 창고에 모아 들이지도 아니하되 너희 천부께서 기르시나니 너희는 이것들보다 귀하지 아니하냐", "te": "Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?"}, {"k": "이사야 26:3", "e": "Isaiah 26:3", "tk": "주께서 심지가 견고한 자를 평강에 평강으로 지키시리니 이는 그가 주를 의뢰함이니이다", "te": "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee."}]}, {"id": "mother", "ko": "어머니", "en": "Mother", "kw": ["어머니", "엄마", "어버이", "모친", "mother", "mom"], "v": [{"k": "잠언 31:25", "e": "Proverbs 31:25", "tk": "능력과 존귀로 옷을 삼고 후일을 웃으며", "te": "Strength and honour are her clothing; and she shall rejoice in time to come."}, {"k": "잠언 31:28", "e": "Proverbs 31:28", "tk": "그 자식들은 일어나 사례하며 그 남편은 칭찬하기를", "te": "Her children arise up, and call her blessed; her husband also, and he praiseth her."}, {"k": "잠언 31:30", "e": "Proverbs 31:30", "tk": "고운 것도 거짓되고 아름다운 것도 헛되나 오직 여호와를 경외하는 여자는 칭찬을 받을 것이라", "te": "Favour is deceitful, and beauty is vain: but a woman that feareth the LORD, she shall be praised."}, {"k": "이사야 66:13", "e": "Isaiah 66:13", "tk": "어미가 자식을 위로함 같이 내가 너희를 위로할 것인즉 너희가 예루살렘에서 위로를 받으리니", "te": "As one whom his mother comforteth, so will I comfort you; and ye shall be comforted in Jerusalem."}, {"k": "잠언 1:8", "e": "Proverbs 1:8", "tk": "내 아들아 네 아비의 훈계를 들으며 네 어미의 법을 떠나지 말라", "te": "My son, hear the instruction of thy father, and forsake not the law of thy mother:"}, {"k": "출애굽기 20:12", "e": "Exodus 20:12", "tk": "네 부모를 공경하라 그리하면 너의 하나님 나 여호와가 네게 준 땅에서 네 생명이 길리라", "te": "Honour thy father and thy mother: that thy days may be long upon the land which the LORD thy God giveth thee."}]}, {"id": "father", "ko": "아버지", "en": "Father", "kw": ["아버지", "아빠", "어버이", "부친", "father", "dad"], "v": [{"k": "잠언 23:24", "e": "Proverbs 23:24", "tk": "의인의 아비는 크게 즐거울 것이요 지혜로운 자식을 낳은 자는 그를 인하여 즐거울 것이니라", "te": "The father of the righteous shall greatly rejoice: and he that begetteth a wise child shall have joy of him."}, {"k": "시편 103:13", "e": "Psalm 103:13", "tk": "아비가 자식을 불쌍히 여김 같이 여호와께서 자기를 경외하는 자를 불쌍히 여기시나니", "te": "Like as a father pitieth his children, so the LORD pitieth them that fear him."}, {"k": "잠언 20:7", "e": "Proverbs 20:7", "tk": "완전히 행하는 자가 의인이라 그 후손에게 복이 있느니라", "te": "The just man walketh in his integrity: his children are blessed after him."}, {"k": "에베소서 6:4", "e": "Ephesians 6:4", "tk": "또 아비들아 너희 자녀를 노엽게 하지 말고 오직 주의 교양과 훈계로 양육하라", "te": "And, ye fathers, provoke not your children to wrath: but bring them up in the nurture and admonition of the Lord."}, {"k": "출애굽기 20:12", "e": "Exodus 20:12", "tk": "네 부모를 공경하라 그리하면 너의 하나님 나 여호와가 네게 준 땅에서 네 생명이 길리라", "te": "Honour thy father and thy mother: that thy days may be long upon the land which the LORD thy God giveth thee."}, {"k": "잠언 4:1", "e": "Proverbs 4:1", "tk": "아들들아 아비의 훈계를 들으며 명철을 얻기에 주의하라", "te": "Hear, ye children, the instruction of a father, and attend to know understanding."}]}, {"id": "children", "ko": "자녀", "en": "Children", "kw": ["자녀", "아이", "아들", "딸", "children", "kids", "son", "daughter"], "v": [{"k": "시편 127:3", "e": "Psalm 127:3", "tk": "자식은 여호와의 주신 기업이요 태의 열매는 그의 상급이로다", "te": "Lo, children are an heritage of the LORD: and the fruit of the womb is his reward."}, {"k": "잠언 22:6", "e": "Proverbs 22:6", "tk": "마땅히 행할 길을 아이에게 가르치라 그리하면 늙어도 그것을 떠나지 아니하리라", "te": "Train up a child in the way he should go: and when he is old, he will not depart from it."}, {"k": "마태복음 19:14", "e": "Matthew 19:14", "tk": "예수께서 가라사대 어린 아이들을 용납하고 내게 오는 것을 금하지 말라 천국이 이런 자의 것이니라 하시고", "te": "But Jesus said, Suffer little children, and forbid them not, to come unto me: for of such is the kingdom of heaven."}, {"k": "요한삼서 1:4", "e": "3 John 1:4", "tk": "내가 내 자녀들이 진리 안에서 행한다 함을 듣는 것보다 더 즐거움이 없도다", "te": "I have no greater joy than to hear that my children walk in truth."}, {"k": "이사야 54:13", "e": "Isaiah 54:13", "tk": "네 모든 자녀는 여호와의 교훈을 받을 것이니 네 자녀는 크게 평강할 것이며", "te": "And all thy children shall be taught of the LORD; and great shall be the peace of thy children."}, {"k": "신명기 6:6", "e": "Deuteronomy 6:6", "tk": "오늘날 내가 네게 명하는 이 말씀을 너는 마음에 새기고", "te": "And these words, which I command thee this day, shall be in thine heart:"}, {"k": "신명기 6:7", "e": "Deuteronomy 6:7", "tk": "네 자녀에게 부지런히 가르치며 집에 앉았을 때에든지 길에 행할 때에든지 누웠을 때에든지 일어날 때에든지 이 말씀을 강론할 것이며", "te": "And thou shalt teach them diligently unto thy children, and shalt talk of them when thou sittest in thine house, and when thou walkest by the way, and when thou liest down, and when thou risest up."}]}, {"id": "shepherd", "ko": "시편 23편", "en": "Psalm 23", "kw": ["시편", "목자", "psalm", "shepherd"], "v": [{"k": "시편 23:1", "e": "Psalm 23:1", "tk": "여호와는 나의 목자시니 내가 부족함이 없으리로다", "te": "The LORD is my shepherd; I shall not want."}, {"k": "시편 23:2", "e": "Psalm 23:2", "tk": "그가 나를 푸른 초장에 누이시며 쉴만한 물 가으로 인도하시는도다", "te": "He maketh me to lie down in green pastures: he leadeth me beside the still waters."}, {"k": "시편 23:3", "e": "Psalm 23:3", "tk": "내 영혼을 소생시키시고 자기 이름을 위하여 의의 길로 인도하시는도다", "te": "He restoreth my soul: he leadeth me in the paths of righteousness for his name’s sake."}, {"k": "시편 23:4", "e": "Psalm 23:4", "tk": "내가 사망의 음침한 골짜기로 다닐찌라도 해를 두려워하지 않을 것은 주께서 나와 함께 하심이라 주의 지팡이와 막대기가 나를 안위하시나이다", "te": "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me."}, {"k": "시편 23:5", "e": "Psalm 23:5", "tk": "주께서 내 원수의 목전에서 내게 상을 베푸시고 기름으로 내 머리에 바르셨으니 내 잔이 넘치나이다", "te": "Thou preparest a table before me in the presence of mine enemies: thou anointest my head with oil; my cup runneth over."}, {"k": "시편 23:6", "e": "Psalm 23:6", "tk": "나의 평생에 선하심과 인자하심이 정녕 나를 따르리니 내가 여호와의 집에 영원히 거하리로다", "te": "Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever."}]}];
